-- Version 1 schema from aa6e45c Entities.kt; v2 nullable additions excluded.
CREATE TABLE IF NOT EXISTS `matches` (`matchId` TEXT NOT NULL, `competitionId` TEXT NOT NULL, `competitionTitle` TEXT NOT NULL, `season` INTEGER NOT NULL, `stage` TEXT NOT NULL, `date` TEXT NOT NULL, `kickoffUtc` TEXT, `status` TEXT NOT NULL, `score` TEXT NOT NULL, `liveDetail` TEXT, `homeTeamId` INTEGER, `home` TEXT NOT NULL, `homeShort` TEXT NOT NULL, `homeBadgeUrl` TEXT, `awayTeamId` INTEGER, `away` TEXT NOT NULL, `awayShort` TEXT NOT NULL, `awayBadgeUrl` TEXT, `venue` TEXT NOT NULL, `leg` INTEGER, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`matchId`));
CREATE INDEX IF NOT EXISTS `index_matches_competitionId_season` ON `matches` (`competitionId`, `season`);
CREATE INDEX IF NOT EXISTS `index_matches_updatedAt` ON `matches` (`updatedAt`);
CREATE TABLE IF NOT EXISTS `standings` (`competitionId` TEXT NOT NULL, `season` INTEGER NOT NULL, `groupName` TEXT NOT NULL, `position` TEXT NOT NULL, `teamId` INTEGER NOT NULL, `teamName` TEXT NOT NULL, `played` TEXT NOT NULL, `won` TEXT NOT NULL, `drawn` TEXT NOT NULL, `lost` TEXT NOT NULL, `goalsFor` TEXT NOT NULL, `goalsAgainst` TEXT NOT NULL, `difference` TEXT NOT NULL, `points` TEXT NOT NULL, `deductions` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`competitionId`, `season`, `groupName`, `position`));
CREATE INDEX IF NOT EXISTS `index_standings_competitionId_season` ON `standings` (`competitionId`, `season`);
CREATE TABLE IF NOT EXISTS `players` (`playerId` TEXT NOT NULL, `season` INTEGER NOT NULL, `competitionId` TEXT NOT NULL, `teamId` INTEGER NOT NULL, `teamName` TEXT NOT NULL, `name` TEXT NOT NULL, `position` TEXT NOT NULL, `jersey` TEXT, `appearances` TEXT, `goals` TEXT, `assists` TEXT, `photoUrl` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`playerId`, `season`, `competitionId`, `teamId`));
CREATE INDEX IF NOT EXISTS `index_players_competitionId_season` ON `players` (`competitionId`, `season`);
CREATE INDEX IF NOT EXISTS `index_players_teamId` ON `players` (`teamId`);
CREATE TABLE IF NOT EXISTS `matchTeams` (`matchId` TEXT NOT NULL, `teamId` INTEGER NOT NULL, `formation` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`matchId`, `teamId`));
CREATE TABLE IF NOT EXISTS `matchLineups` (`matchId` TEXT NOT NULL, `teamId` INTEGER NOT NULL, `role` TEXT NOT NULL, `sortIndex` INTEGER NOT NULL, `playerId` TEXT NOT NULL, `playerName` TEXT NOT NULL, `jersey` TEXT, `position` TEXT NOT NULL, `photoUrl` TEXT, `goals` TEXT, `appearances` TEXT, `assists` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`matchId`, `teamId`, `role`, `sortIndex`));
CREATE INDEX IF NOT EXISTS `index_matchLineups_matchId` ON `matchLineups` (`matchId`);
CREATE TABLE IF NOT EXISTS `matchStats` (`matchId` TEXT NOT NULL, `label` TEXT NOT NULL, `home` TEXT, `away` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`matchId`, `label`));
CREATE INDEX IF NOT EXISTS `index_matchStats_matchId` ON `matchStats` (`matchId`);
CREATE TABLE IF NOT EXISTS `matchEvents` (`rowId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `matchId` TEXT NOT NULL, `minute` INTEGER NOT NULL, `added` INTEGER NOT NULL, `seq` INTEGER NOT NULL, `label` TEXT NOT NULL, `updatedAt` TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS `index_matchEvents_matchId` ON `matchEvents` (`matchId`);
CREATE TABLE IF NOT EXISTS `f1Races` (`season` INTEGER NOT NULL, `round` INTEGER NOT NULL, `name` TEXT NOT NULL, `circuit` TEXT NOT NULL, `country` TEXT NOT NULL, `date` TEXT NOT NULL, `utcTime` TEXT, `circuitId` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`season`, `round`));
CREATE TABLE IF NOT EXISTS `f1Sessions` (`season` INTEGER NOT NULL, `round` INTEGER NOT NULL, `title` TEXT NOT NULL, `date` TEXT NOT NULL, `time` TEXT, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`season`, `round`, `title`));
CREATE TABLE IF NOT EXISTS `f1Results` (`season` INTEGER NOT NULL, `round` INTEGER NOT NULL, `position` TEXT NOT NULL, `name` TEXT NOT NULL, `team` TEXT NOT NULL, `points` TEXT NOT NULL, `detail` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`season`, `round`, `position`));
CREATE INDEX IF NOT EXISTS `index_f1Results_season_round` ON `f1Results` (`season`, `round`);
CREATE TABLE IF NOT EXISTS `f1Standings` (`season` INTEGER NOT NULL, `kind` TEXT NOT NULL, `round` TEXT NOT NULL, `position` TEXT NOT NULL, `name` TEXT NOT NULL, `team` TEXT NOT NULL, `points` TEXT NOT NULL, `detail` TEXT NOT NULL, `updatedAt` TEXT NOT NULL, PRIMARY KEY(`season`, `kind`, `round`, `position`));
CREATE INDEX IF NOT EXISTS `index_f1Standings_season_kind` ON `f1Standings` (`season`, `kind`);
CREATE TABLE IF NOT EXISTS `sourceLog` (`url` TEXT NOT NULL, `fetchedUtc` TEXT NOT NULL, `kind` TEXT NOT NULL, PRIMARY KEY(`url`));
CREATE TABLE IF NOT EXISTS `meta` (`key` TEXT NOT NULL, `value` TEXT NOT NULL, PRIMARY KEY(`key`));
